/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls } from '../core/renderer';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { exChase } from './chase';
import { exShowChooser } from './chooser';
import { exNight, exNightBind, exNightStep } from './nightShows';
import type { SwingController } from '../bridges/song-han/SwingController';

const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung

let glider: THREE.Group | null = null;
let state: GliderState | null = null;
let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi

const active = () => cam.mode === 'glider' && state !== null;

/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
function exShowSpeed(): void {
  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
  if (t === readout) return;
  readout = t;
  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
}

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!);
  exChase(camera, controls.target, state!, dt);
  exShowSpeed();
  exNightStep(dt);
}

export const explore = {
  active,
  nightShows: exNight,
  get state() { return state; },
  get glider() { return glider; },
  start(): void {
    state = exCreate();
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  update(dt: number): void {
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
    else location.replace(u.toString());
  },
};

export function setupExplore(ctrl: SwingController): void {
  exNightBind(ctrl);
  window.addEventListener('keydown', (e) => {
    if (!active()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
}
/* ===== Dù lượn nhiều người: kết nối WebSocket tới máy chủ ===== */
import type { ClientMsg, ServerMsg } from './protocol';

export interface Transport {
  send(m: ClientMsg): void;
  close(): void;
  onMessage: (m: ServerMsg) => void;
  onClose: () => void;
}

// Mở WebSocket; reject khi lỗi hoặc quá hạn timeoutMs
export function exConnect(url: string, timeoutMs: number): Promise<Transport> {
  return new Promise<Transport>((resolve, reject) => {
    let ws: WebSocket;
    try { ws = new WebSocket(url); } catch (e) { reject(e); return; }
    let opened = false;
    const tm = setTimeout(() => { if (!opened) { try { ws.close(); } catch (e) { /* bỏ qua */ } reject(new Error('timeout')); } }, timeoutMs);
    const t: Transport = {
      send: m => { if (ws.readyState === 1) ws.send(JSON.stringify(m)); },
      close: () => { try { ws.close(); } catch (e) { /* bỏ qua */ } },
      onMessage: () => {},
      onClose: () => {}
    };
    ws.onopen = () => { opened = true; clearTimeout(tm); resolve(t); };
    ws.onmessage = ev => {
      let m: ServerMsg;
      try { m = JSON.parse(String(ev.data)); } catch (e) { return; }
      if (m && typeof m.t === 'string') t.onMessage(m);
    };
    ws.onerror = () => { if (!opened) { clearTimeout(tm); reject(new Error('ws error')); } };
    ws.onclose = () => { clearTimeout(tm); if (!opened) reject(new Error('closed')); else t.onClose(); };
  });
}
/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018). */
const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }

export class ExTrack {
  private buf = new Float64Array(N * W);
  private head = 0;      // chỉ số ô sẽ ghi tiếp
  private n = 0;         // số mẫu đang có
  get count(): number { return this.n; }

  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
    const o = this.head * W, b = this.buf;
    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
    this.head = (this.head + 1) % N;
    if (this.n < N) this.n++;
  }

  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
  sample(t: number, out: ExPose): boolean {
    if (this.n === 0) return false;
    const b = this.buf, first = (this.head + N - this.n) % N * W;
    const last = ((this.head + N - 1) % N) * W;
    let a = first, c = first;
    if (t >= b[last]) a = c = last;
    else if (t > b[first]) {
      for (let i = 0; i < this.n - 1; i++) {
        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
        if (t <= b[q]) { a = p; c = q; break; }
      }
    }
    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
    let dy = b[c + 4] - b[a + 4];
    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
    out.yaw = b[a + 4] + dy * k;
    out.bank = b[a + 5] + (b[c + 5] - b[a + 5]) * k;
    return true;
  }

  reset(): void { this.n = 0; this.head = 0; }
}
/* ===== Dù lượn nhiều người: thông số dùng chung khách + máy chủ (không import gì; config.ts import file này) ===== */
export const multiParams = {
  url: 'wss://danang-sky.tuanlv5490.workers.dev/sky', // địa chỉ WebSocket của máy chủ Cloudflare; rỗng = chỉ bay một mình
  slots: 5,              // số chỗ bay cùng lúc (theo thiết kế)
  nameMax: 9,            // số grapheme tối đa của tên hiển thị (ước lượng)
  sendHz: 5,             // lần/s khách gửi vị trí (ước lượng, đo ở giai đoạn đầu)
  broadcastMs: 100,      // ms tối thiểu giữa hai lần máy chủ phát gói vị trí gộp (ước lượng)
  posMaxPerSec: 8,       // gói pos tối đa một kết nối được gửi trong 1 s, quá thì bỏ (ước lượng)
  heartbeatMs: 3000,     // ms giữa hai nhịp sống khi không đổi vị trí (ước lượng)
  slotTimeoutMs: 10000,  // ms không có tin thì máy chủ trả slot (ước lượng)
  sweepMs: 10000,        // ms giữa hai lần máy chủ quét slot hết hạn (ước lượng)
  connectTimeoutMs: 4000, // ms chờ kết nối WebSocket trước khi coi là lỗi (ước lượng)
  idleMs: 60000,         // ms không chạm phím thì hiện hỏi "Bạn còn đó không?" (ước lượng)
  idleWarnMs: 15000,     // ms đếm ngược sau khi hỏi, hết thì trả slot (ước lượng)
  maxConns: 200,         // số kết nối đồng thời tối đa của phòng (ước lượng)
  maxMsgBytes: 256,      // byte tối đa của một tin nhận từ khách (ước lượng)
  interpSends: 2.5,      // độ trễ nội suy, tính theo số chu kỳ gửi (ước lượng)
  spawnSpread: 30,       // m lệch điểm cất cánh theo slot để không chồng nhau (ước lượng)
  labelBelow: 9,         // m đặt nhãn tên bên dưới cánh dù (ước lượng)
  colors: ['#2f9e6e', '#e8892b', '#a855c7', '#2a8fd6', '#e0c02e'], // màu cánh theo slot (ước lượng)
  bounds: { x0: -2600, x1: 3600, z0: -5600, z1: 2800 }, // m — khung bay, phải bằng CONFIG.explore.bounds (có test kiểm)
  floor: 7,              // m — độ cao tối thiểu, phải bằng CONFIG.explore.floor
  ceiling: 800           // m — độ cao tối đa, phải bằng CONFIG.explore.ceiling
};
/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string }
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number }
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string }

// f: mỗi phần tử [slot, x, y, z, yaw, bank]
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[] }
  | { t: 'joined'; slot: number }
  | { t: 'rejected'; why: 'full' | 'name' }
  | { t: 'pos'; f: number[][] }
  | { t: 'released' };

// Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng; rỗng hoặc quá nameMax grapheme → null
export function exSanitizeName(raw: string): string | null {
  if (typeof raw !== 'string') return null;
  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '‍' ? c : '')).trim();
  if (!s) return null;
  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let n = 0;
  for (const _ of seg.segment(s)) if (++n > multiParams.nameMax) return null;
  return s;
}
/* ===== Dù lượn nhiều người: dù của người bay cùng =====
   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
   Vị trí nhận 5 lần/s được nội suy, lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { CONFIG } from '../../config';
import { exBuildGlider, exPlaceGlider } from '../glider';
import type { GliderState } from '../flight';
import { ExTrack, type ExPose } from './interp';
import type { Flyer } from './protocol';

const M = CONFIG.explore.multi;

interface RemoteSlot {
  name: string | null;        // null = slot trống
  group: THREE.Group | null;
  track: ExTrack;
  pose: ExPose;               // đệm lấy mẫu
  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
  live: boolean;              // đã có mẫu và đang hiện
}

const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
}));
let me = -1;

function hide(s: RemoteSlot): void {
  s.track.reset(); s.live = false;
  if (s.group) s.group.visible = false;
}

export const exRemotes = {
  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
  sync(flyers: Flyer[], mySlot: number): void {
    me = mySlot;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      let name: string | null = null;
      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
      if (name === null) { s.name = null; hide(s); continue; }
      if (name !== s.name) {
        s.name = name; hide(s);
        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; scene.add(s.group); }
      }
    }
  },

  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank]; chỉ nhận slot đã biết chủ và không phải của mình */
  onPos(f: number[][], nowMs: number): void {
    for (const e of f) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.name === null) continue;
      s.track.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
    }
  },

  update(nowMs: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (const s of slots) {
      if (s.name === null || !s.group) continue;
      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
      const p = s.pose;
      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
      exPlaceGlider(s.group, s.state);
      s.group.visible = s.live = true;
    }
  },

  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
  slotState(slot: number): GliderState | null {
    const s = slots[slot];
    return s && s.live ? s.state : null;
  },

  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
  clear(): void {
    me = -1;
    for (const s of slots) { s.name = null; hide(s); }
  }
};
/* ===== Dù lượn nhiều người: máy trạng thái phiên (không DOM, không three) ===== */
import type { Flyer, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  mySlot = -1;
  watched = -1;       // slot đang xem, -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n)) {}

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  join(name: string): void {
    this.name = name; this.notice = '';
    this.t?.send({ t: 'join', name });
  }

  // Rời chỗ bay (do idle): trả slot, chuyển sang xem
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.toWatching();
    this.onChange();
  }

  sendPos(x: number, y: number, z: number, yaw: number, bank: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác
  private fixWatched(): void {
    const ids = this.flyers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < multiParams.slots;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  private recv(m: ServerMsg): void {
    if (this.disposed) return;
    switch (m.t) {
      case 'lobby':
        this.flyers = m.flyers;
        if (this.first) {
          this.first = false;
          if (m.flyers.length >= multiParams.slots) this.phase = 'watching';
          else this.phase = 'lobby';
        }
        // đang bay: danh sách chỉ để hiển thị
        this.fixWatched();
        break;
      case 'joined':
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
        this.fixWatched();
        break;
      case 'rejected':
        if (m.why === 'name') this.notice = 'nameBad';
        else {
          if (this.phase === 'watching') this.notice = 'late';
          else { this.phase = 'watching'; }
          this.fixWatched();
        }
        break;
      case 'pos':
        this.onPos(m.f);
        return;
      case 'released':
        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
        break;
    }
    this.onChange();
  }
}
