    if (origin) headers.Origin = origin;
    const req = http.request({ host: '127.0.0.1', port: PORT, path: '/sky', headers });
    req.on('response', r => { res(r.statusCode); r.resume(); });
    req.on('upgrade', (r, sock) => { res(r.statusCode); sock.destroy(); });
