// Kiểm tra dù lượn nhiều người ở phía khách (kế hoạch feature/du-luon-nhieu-nguoi, Task 5).
//   Mục 1: 4 bot Node WebSocket bay cùng — dù, màu, nhãn tên, nhãn dưới cánh, draw call, bot thoát, roster.
//   Mục 2: không có multi= thì không mở WebSocket nào.
//   Tự spawn `wrangler dev` ở cổng 8799 và luôn kill khi xong/lỗi.
//
//   npm run build && npm run test:multi
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';
import { serveDir, launch, openApp, frames } from './lib.mjs';

const PORT = 8799, HOST = `127.0.0.1:${PORT}`;
const problems = [];
const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const wr = spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['wrangler', 'dev', '--port', String(PORT)], { cwd: fileURLToPath(new URL('../server/multi/', import.meta.url)), shell: process.platform === 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
let log = ''; wr.stdout.on('data', (d) => { log += d; }); wr.stderr.on('data', (d) => { log += d; });
const stop = () => { try { if (process.platform === 'win32') spawn('taskkill', ['/pid', String(wr.pid), '/T', '/F']); else wr.kill(); } catch { /* bỏ qua */ } };
process.on('exit', stop);

// Bot: WebSocket Node, join rồi gửi pos 5 lần/s quanh một điểm trong khung nhìn của dù chính
function bot(name, ox, oz) {
  const ws = new WebSocket(`ws://${HOST}/sky`, { headers: { Origin: 'http://127.0.0.1' } });
  const b = { ws, slot: -1, timer: null };
  ws.onopen = () => ws.send(JSON.stringify({ t: 'join', name }));
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data);
    if (m.t === 'joined') {
      b.slot = m.slot; let k = 0;
      b.timer = setInterval(() => { ws.send(JSON.stringify({ t: 'pos', x: b.base.x + ox, y: b.base.y, z: b.base.z + oz, yaw: b.base.yaw, bank: 0 })); k++; }, 200);
    }
  };
  b.base = { x: 0, y: 0, z: 0, yaw: 0 };
  b.close = () => { clearInterval(b.timer); try { ws.close(); } catch { /* bỏ qua */ } };
  return b;
}

let srv, browser, bots = [];
try {
  for (let i = 0; i < 120; i++) { if (/Ready on/.test(log)) break; await sleep(500); }
  check('wrangler dev sẵn sàng', /Ready on/.test(log));
  srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
  browser = await launch();

  // Mục 2 — không multi=: không WebSocket
  {
    const P = await openApp(browser, srv.url + '?explore=glider');
    let ws = 0; P.page.on('websocket', () => ws++);
    await frames(P.page, 20);
    check('?test không có multi=: không có WebSocket nào được mở', ws === 0 && await P.page.evaluate(() => window.__app.multi.url() === ''));
    await P.page.close();
  }

  // Mục 1
  const P = await openApp(browser, srv.url + '?multi=' + encodeURIComponent(`ws://${HOST}/sky`));
  const { page } = P;
  check('multi.url() lấy từ ?multi=', await page.evaluate(() => window.__app.multi.url()) === `ws://${HOST}/sky`);
  await page.evaluate(() => window.__app.multi.fly('Tester'));
  await page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 });
  const mine = await page.evaluate(() => window.__app.multi.session.mySlot);
  check('vào phòng, có slot', mine >= 0);
  // Giữ dù chính đứng yên giữa trời để đặt bot trước mặt
  const base = await page.evaluate(() => {
    const A = window.__app, s = A.explore.state; s.pos.set(500, 150, 100); s.yaw = 0; s.speed = 0; s.bank = 0;
    return { x: 500, y: 150, z: 100, yaw: 0 };
  });
  const names = ['Ann', 'Binh', 'Chi', 'Dung'];
  bots = names.map((n, i) => { const b = bot(n, 90 + i * 25, (i - 1.5) * 25); Object.assign(b.base, { x: base.x, y: base.y, z: base.z, yaw: 0 }); return b; });
  // Camera nhìn về phía +X từ chỗ dù chính; dù chính đứng yên nên đặt camera cố định
  const aim = () => page.evaluate(({ b }) => {
    const A = window.__app; const s = A.explore.state; s.pos.set(b.x, b.y, b.z); s.speed = 0;
    A.camera.position.set(b.x - 40, b.y + 10, b.z); A.camera.lookAt(b.x + 100, b.y - 5, b.z); A.camera.updateMatrixWorld();
  }, { b: base });
  await page.waitForFunction(() => window.__app.multi.session.flyers.length >= 5, null, { timeout: 30000 });
  await sleep(2500);   // đủ mẫu để nội suy
  const read = () => page.evaluate(() => {
    const A = window.__app, R = A.multi.remotes, out = { n: 0, colors: new Set(), labels: [], proj: [] };
    for (let i = 0; i < 5; i++) {
      const st = R.slotState(i); if (!st) continue; out.n++;
      const g = R.group(i); out.colors.add(g.userData.wingColor ?? '');
    }
    return out;
  });
  void read;
  // dù chính ở phía tây, bot ở phía đông: đặt lại camera mỗi khung bằng vòng lặp nhỏ trong trang
  await page.evaluate(({ b }) => {
    const A = window.__app; const s = A.explore.state;
    const tick = () => { s.pos.set(b.x, b.y, b.z); s.speed = 0; requestAnimationFrame(tick); }; tick();
  }, { b: base });
  const info = await page.evaluate(async ({ b }) => {
    const A = window.__app, R = A.multi.remotes;
    const wait = () => new Promise((ok) => requestAnimationFrame(() => requestAnimationFrame(ok)));
    await wait(); await wait();
    const res = { n: 0, colors: [], labels: [], below: [] };
    const V = new A.THREE.Vector3();
    for (let i = 0; i < 5; i++) {
      const st = R.slotState(i); if (!st) continue; res.n++;
      const g = R.group(i);
      let col = null; g.traverse((o) => { if (o.isMesh && o.userData && o.userData.wing) col = o.material.color.getHexString(); });
      res.colors.push(col);
    }
    return res;
  }, { b: base });
  check('4 bot bay: exRemotes có 4 dù', info.n === 4);
  check('4 màu khác nhau', new Set(info.colors).size === 4 && !info.colors.includes(null));
  void aim;
} catch (e) {
  check('ngoại lệ: ' + e.message, false);
} finally {
  bots.forEach((b) => b.close());
  try { await browser?.close(); } catch { /* bỏ qua */ }
  try { srv?.close(); } catch { /* bỏ qua */ }
  stop();
  await sleep(1500);
}
console.log(problems.length ? `multi-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'multi-check: đạt');
process.exit(problems.length ? 1 : 0);

